\centering
\footnotesize
\caption{Cross-domain $\Kempirical$ comparison. $\Kempirical{=}2$ for C4, Wikipedia, and Code; $\Kempirical{=}3$ for arXiv (three families confirmed in text; representative rows shown).}
\label{tab:domain_kstar}
\resizebox{\columnwidth}{!}{%
\begin{tabular}{llccc}
\toprule
\textbf{Domain} & \textbf{Model} & \textbf{1v2 $\auc$} & \textbf{2v3 $\auc$} & $\Kempirical$ \\
\midrule
